import{_ as t,o as a,c as o,a6 as r}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse('{"title":"Gap detectors & exposure","description":"Every Test Map detector with the class it reports, what it needs and its evidence, the exposure factors that rank gaps, and what the graph includes.","frontmatter":{"title":"Gap detectors & exposure","description":"Every Test Map detector with the class it reports, what it needs and its evidence, the exposure factors that rank gaps, and what the graph includes.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/gap-detectors.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/gap-detectors.html"}],["meta",{"property":"og:title","content":"Gap detectors & exposure | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Every Test Map detector with the class it reports, what it needs and its evidence, the exposure factors that rank gaps, and what the graph includes."}]]},"headers":[],"relativePath":"reference/gap-detectors.md","filePath":"reference/gap-detectors.md","lastUpdated":1794055165000}'),s={name:"reference/gap-detectors.md"};function n(d,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="gap-detectors-exposure" tabindex="-1">Gap detectors &amp; exposure <a class="header-anchor" href="#gap-detectors-exposure" aria-label="Permalink to &quot;Gap detectors &amp; exposure&quot;">​</a></h1><p>The <a href="/guide/concepts.html#detector">detectors</a> that turn the <a href="/features/scenario-gaps.html">Test Map</a> into scenario gaps, the <strong>exposure</strong> score that ranks them, and the rules that decide what the graph holds. Evidence counts use the last 30 runs of the project&#39;s default branch: never a pull-request run, a probe or Flake Lab run, a bisect step or a reproduction, nor a run flagged as an environment incident. <em>Changed, unreached</em> reads the window of <a href="/features/uncovered-changes.html#one-rule-for-every-changed-file">change coverage</a> instead.</p><h2 id="detectors" tabindex="-1">Detectors <a class="header-anchor" href="#detectors" aria-label="Permalink to &quot;Detectors&quot;">​</a></h2><p>The Test Map is recomputed after every run of the default branch, nightly, and on demand (<strong>Recompute</strong> on the Gaps tab), always for the default branch whatever branch ran last. Every detector reads the runs the <a href="/guide/capture-fixtures.html">capture fixtures</a> record; <strong>Needs</strong> names what else it reads, and a detector stays silent without it.</p><table tabindex="0"><thead><tr><th>Detector</th><th>Class</th><th>Finds</th><th>Needs</th><th>Confidence</th><th>Example evidence</th></tr></thead><tbody><tr><td><strong>Success only</strong><br><code>success-only</code></td><td>blind-spot</td><td>a route observed at least five times, always with a 2xx or 3xx status: its error paths never ran</td><td>nothing more</td><td>observations ÷ 20, plus 0.3 when the route documents an error status; at most 1</td><td><code>Observed 412 times over the last 30 runs, always 200</code></td></tr><tr><td><strong>Declared, never hit</strong><br><code>declared-never-hit</code></td><td>blind-spot</td><td>a route or page the application declares that no test reaches</td><td>a <a href="/features/scenario-gaps.html#declared-surface">declared surface</a></td><td>0.7</td><td><code>Declared in OpenAPI · 0 tests in 30 runs · documents 200, 404</code></td></tr><tr><td><strong>Surface drift</strong><br><code>surface-drift</code></td><td>blind-spot</td><td>a route, page, control, link, handler or dependency first seen in the latest run that no test reaches (a handler through the routes it serves, a dependency through the handlers that call it); never a feature, and nothing in the run that built the graph first</td><td>nothing more</td><td>0.4</td><td><code>Appeared in run #830; no test reaches it yet</code></td></tr><tr><td><strong>Control nobody exercises</strong><br><code>control-nobody-exercises</code></td><td>blind-spot</td><td>a control on a page that no test&#39;s locator targets</td><td>the page inventory and the <a href="/features/locator-usage.html">locator index</a></td><td>0.3 plus 0.1 per page, at most 0.8</td><td><code>On 12 page(s) · no locator targets it</code></td></tr><tr><td><strong>Reachable, unvisited</strong><br><code>reachable-unvisited</code></td><td>blind-spot</td><td>a page other pages link to that no test navigates to</td><td>the page inventory</td><td>0.4 plus 0.1 per linking page, at most 0.8</td><td><code>Linked from 7 page(s) · never navigated to</code></td></tr><tr><td><strong>Escaped defect</strong><br><code>escaped-defect</code></td><td>blind-spot</td><td>a page with <a href="/features/bug-reports.html">bug reports</a> no test names yet, one gap per page</td><td>Piwi Picker sending reports</td><td>0.6 plus 0.1 per further report, at most 1</td><td><code>Bug report #37: Coupon not applied to the total — no test names it yet</code></td></tr><tr><td><strong>Fixed without a regression test</strong><br><code>fixed-without-test</code></td><td>blind-spot</td><td>a <a href="/features/bug-reports.html">bug report</a> closed in the last 180 days while no test names it</td><td>Piwi Picker sending reports</td><td>0.7</td><td><code>Bug report #2 was fixed without a regression test: Gift card balance shown twice</code></td></tr><tr><td><strong>Changed, unreached</strong><br><code>changed-unreached</code></td><td>blind-spot</td><td>an <a href="/features/uncovered-changes.html#one-rule-for-every-changed-file">uncovered change</a>, at pull-request time: a changed file Piwi can observe that no test reached, in the run or the last 30, and no suite ran a changed line of</td><td>an SCM token</td><td>0.9</td><td><code>+41 −3 · no test in run #812 or in the last 30 runs</code></td></tr><tr><td><strong>New error path</strong><br><code>new-error-path</code></td><td>blind-spot</td><td>at pull-request time, an error status (400 to 599) the change makes a route&#39;s handler answer with or throw, which no run of the route answered with, this one included</td><td>an SCM token and a pull request</td><td>0.55</td><td><code>Adds 422 to POST /api/orders · never observed</code></td></tr><tr><td><strong>New control</strong><br><code>new-control</code></td><td>blind-spot</td><td>at pull-request time, a button, field, select or switch the change adds to a page file, on a page a test reaches, named by its static label, placeholder, name or text</td><td>an SCM token and a pull request</td><td>0.5</td><td><code>Adds button &quot;Apply promo&quot; on /checkout</code></td></tr><tr><td><strong>Intent without a test</strong><br><code>intent-without-test</code></td><td>blind-spot</td><td>at pull-request time, a pull request whose title&#39;s words (half of them at least) no test&#39;s title, describe path, tags or feature holds</td><td>an SCM token and a pull request</td><td>0.4</td><td><code>feat: apply a promo discount · no test title, tag or feature matches</code></td></tr><tr><td><strong>Single covering test</strong><br><code>single-covering-test</code></td><td>fragile</td><td>a node exactly one trusted test reaches, or that only untrusted tests reach</td><td>nothing more</td><td>0.5; 0.6 when only untrusted tests reach it</td><td><code>Only checkout › coupon reaches this</code>; <code>Only toggles dark mode (flaky) reaches this</code></td></tr><tr><td><strong>Orphan test</strong><br><code>orphan-test</code></td><td>fragile</td><td>a test whose every reached node went unseen through the default branch&#39;s last 30 complete runs</td><td>nothing more</td><td>0.4</td><td><code>All 3 node(s) it reaches disappeared from recent runs</code></td></tr><tr><td><strong>Fix did not hold</strong><br><code>fix-did-not-hold</code></td><td>fragile</td><td>a failure cluster whose fix later regressed</td><td>nothing more</td><td>0.6</td><td><code>Fixed in a1b2c3d · regressed 6 days later</code></td></tr><tr><td><strong>Incidental catch</strong><br><code>incidental-catch</code></td><td>fragile</td><td>a failure cluster whose recorded fix changed one to three files, no test file among them, that none of the tests it failed is about by name or reaches</td><td><a href="/guide/source-control.html">source control</a></td><td>0.45</td><td><code>src/pricing/rounding.ts is caught only incidentally</code></td></tr><tr><td><strong>Not noticed</strong><br><code>not-noticed</code></td><td>false-comfort</td><td>a route a probe broke while no test noticed (a delay never counts)</td><td><a href="/features/probes.html">probes</a></td><td>0.8</td><td><code>A probe (status-500) on POST /api/orders did not make checkout › pay fail</code></td></tr><tr><td><strong>Passed with errors</strong><br><code>passed-with-errors</code></td><td>false-comfort</td><td>a test whose newest execution in the default branch&#39;s last 30 runs passed while the application reported an error: a 5xx from one of its routes, a backend log at error level, or a console error from its own origin</td><td>nothing more; backend logs need the <a href="/guide/backend-logs.html">instrumentation</a></td><td>0.6</td><td><code>Passed · run #73 · the backend logged an error on PATCH /api/orgs/current</code></td></tr><tr><td><strong>Assertion-light</strong><br><code>assertion-light</code></td><td>false-comfort</td><td>a page some test asserts on, every check there only that an element is visible, hidden, attached or in the viewport</td><td>the locator index</td><td>0.4</td><td><code>2 tests assert on this page, only that elements are present</code></td></tr><tr><td><strong>Catalog method, no test calls</strong><br><code>catalog-method-no-test-calls</code></td><td>blind-spot</td><td>a page-object method or helper on a reached page that no test runs</td><td>the <a href="/features/test-functions.html">test functions catalog</a></td><td>0.5</td><td><code>./pages/UsersPage · goToNextPage · page reached by 3, called by 0</code></td></tr><tr><td><strong>Code nobody executes</strong><br><code>code-not-executed</code></td><td>blind-spot</td><td>the functions of a file no suite ran in the default branch&#39;s newest <a href="/features/combined-coverage.html">combined coverage</a>, or a file recorded by line none of whose lines ran; the 30 files with the most, one gap each</td><td>a coverage report or run coverage</td><td>0.4 plus 0.3 times the share of its functions not run; 0.6 for a whole file</td><td><code>Functions at lines 12–20, 22–30 · no suite ran them at 9a8b7c6</code></td></tr><tr><td><strong>Single covering function</strong><br><code>single-covering-function</code></td><td>fragile</td><td>the functions of a file exactly one test runs in the tests&#39; latest coverage on the default branch, quarantined tests left out, or that only quarantined tests run; the 30 files with the most, one gap each</td><td>per-test <a href="/features/code-reach.html">code reach</a></td><td>0.5</td><td><code>Only checkout pays runs the functions at lines 7–9</code></td></tr><tr><td><strong>Error path never executed</strong><br><code>error-path-not-executed</code></td><td>blind-spot</td><td>a <code>catch</code> block, a <code>throw</code>, or a statement answering with an error status (<code>TypedResults.NotFound()</code>, <code>res.status(409)</code>) that no suite ran, inside a function that ran (inside a file that ran, when the coverage records it by line): the code-level form of <em>Success only</em>. The 30 files that ran with the most lines not run, read at the commit&#39;s version</td><td>a coverage report or run coverage, and the <a href="/guide/source-control.html">source control</a> connection to read the files</td><td>0.7</td><td><code>Line 59 · return TypedResults.NotFound(); · its function ran, this never did</code></td></tr><tr><td><strong>Unprobed dependency</strong><br><code>unprobed-dependency</code></td><td>false-comfort</td><td>a dependency a route&#39;s handler calls that no probe has decided</td><td>server spans</td><td>0.3 plus 0.1 per calling route, at most 0.7</td><td><code>Called by 4 route(s) · no probe has checked what happens when it fails</code></td></tr><tr><td><strong>Not handled</strong><br><code>not-handled</code></td><td>unhandled, degraded</td><td>the application did not cope with a server probe&#39;s fault; a finding, not a gap</td><td><a href="/features/probes.html#server-probes">server probes</a></td><td>1 unhandled, 0.5 degraded</td><td><code>A server probe made POST /api/orders fail; the application did not handle it</code></td></tr></tbody></table><p><em>Error path never executed</em> scans brace-syntax source (TypeScript, JavaScript, C#, Java): a comment line is skipped, and a brace inside a string can end a <code>catch</code> block early. It runs on <strong>Recompute</strong> and the nightly sweep, which read the files through the source control connection; a file the provider cannot serve keeps its gap as it was.</p><p><em>Passed with errors</em> leaves out a console line from another origin&#39;s script and the browser&#39;s own <em>Failed to load resource</em> line. A response no server sent, such as one the test&#39;s route handler fulfilled, is no 5xx of the application, and a test that fulfills a failing response means to see the page fail, so its console errors do not count either. <em>Assertion-light</em> counts any other matcher (a text, a count, a value, an attribute) as a value check, and so is a read of an element the index cannot name, or a visible element found by a text holding a number (<code>getByText(&#39;Total: $42.00&#39;)</code>); an <code>expect</code> on no locator, such as a downloaded file&#39;s name, never reaches the index, so a page checked only that way reads as light. A test calls a catalog method when one of its default-branch locator uses does what one of the method&#39;s steps does, on the element that step names by test id or name, on a page its URL pattern matches. A method whose every target comes from a parameter gets no decision.</p><p>A trusted test is judged on the default branch&#39;s last 30 runs: it did not pass only after a retry in any of them, did not flip between failing and passing three times across them, did not fail each of its last three, is not quarantined, and was neither skipped nor left unrun in the newest it ran in. A test with no run among them stays trusted. <em>Surface drift</em> raises a node in the run it first appears in; the gap then stays open until any test reaches the node or the node leaves the graph, unless you dismiss it or close it with <em>Covered by</em> first. A node only untrusted tests reach is then a <em>Single covering test</em> gap. <em>Changed, unreached</em> is covered on <a href="/features/uncovered-changes.html">Uncovered changes in pull requests</a>: its gap closes once a test reaches the file, or a later diff no longer counts the file; an accepted gap closes only once a test reaches the file. A file no later diff reads, such as the old path of a rename or a file of an abandoned pull request, keeps its gap until a test reaches it or it is triaged. A finding never closes itself; triage it.</p><p>Runs record reach to routes and pages: a test reaches every route its page requested, every page it ran a locator call on, and the page it ended on. Each recompute adds reach to controls and links from the default branch&#39;s <a href="/features/locator-usage.html">locator index</a>, for uses seen in the last 180 days. A test reaches a control when one of its locators names it by role and name, when an alternative captured for that locator does, or when the name matches as Playwright matches it without <code>exact</code> (a case-insensitive part of exactly one name of that role). A label, placeholder or title reaches the one input-like control (textbox, combobox, checkbox, radio, switch, …) carrying that name. Triage adds reach too (<em>covered by</em> or <em>covered elsewhere</em>), but <em>Control nobody exercises</em> stays silent until a locator reaches some control on the project. A test that clicks or fills an element no node matches, through a test id or a CSS selector, might have used any control on that page, so <em>Control nobody exercises</em>, <em>Single covering test</em> and <em>Surface drift</em> raise none of those controls.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>A gap&#39;s score is its detector&#39;s confidence (the table above) times its <strong>exposure</strong>, the geometric mean of four factors. Each factor is kept between 0.1 and 1, so a missing input lowers the score without zeroing it.</p><table tabindex="0"><thead><tr><th>Factor</th><th>From</th><th>Reaches 1 at</th></tr></thead><tbody><tr><td><strong>Churn</strong></td><td>commits touching the files: on a pull request, among the base branch&#39;s newest twelve in the last 90 days</td><td>12 commits</td></tr><tr><td><strong>Age</strong></td><td>on a pull request, the days since the oldest of those commits; older weighs more, since escaped defects concentrate there. The 90-day scan stops it near 0.25</td><td>one year</td></tr><tr><td><strong>Escape history</strong></td><td>whether a file was part of a failure cluster&#39;s fixing commit, or a bug report from the last 180 days names the gap&#39;s page (the page holding its control)</td><td>yes, else 0.1</td></tr><tr><td><strong>Priority</strong></td><td>the highest <a href="/reference/test-metadata.html#ownership-metadata-piwi-annotations"><code>piwi:priority</code></a> of the tests reaching the node: critical 1, high 0.7, medium 0.4, low 0.2</td><td>critical</td></tr></tbody></table><p>Churn, age and escape history come from the <a href="/guide/source-control.html">source control</a> connection and apply to the files a pull request changed. A gap on a route, a handler or a dependency draws churn and escape history from the handler files behind it, and a gap on a file&#39;s code from that file, read from the diffs default-branch runs recorded over the last 90 days. Each run diffs from its last green run, so churn counts distinct diffs, and the runs of a red streak count once. Escape history marks the files in the diff that ended on a fixing commit, which holds every change since the last green run. Age needs each file&#39;s history, so it stays at 0.1 there. The other detectors rank by priority and confidence. A finding ranks by its severity (1 for unhandled, 0.5 for degraded) times the route&#39;s reach.</p><h2 id="precision" tabindex="-1">Precision <a class="header-anchor" href="#precision" aria-label="Permalink to &quot;Precision&quot;">​</a></h2><p>Each verdict on a gap counts for or against its detector, on that project:</p><ul><li><strong>For</strong>: accepted at any point, or closed with <strong>Covered by</strong>, even once the gap later closes, unless it was then dismissed as <em>wrong</em> or <em>covered elsewhere</em>.</li><li><strong>Against</strong>: dismissed as <em>wrong</em>, or as <em>covered elsewhere</em> (no test was missing). On a finding, <em>covered elsewhere</em> counts for neither.</li><li><strong>Neither</strong>: dismissed as <em>not worth testing</em>, or with no reason, and never accepted.</li></ul><p>A detector&#39;s precision is its share of verdicts <em>for</em>. Below 60%, on a project with twenty or more verdicts, the detector <a href="/features/scenario-gaps.html#triage">mutes itself</a> there: its rows leave the pull-request comment, the Gaps digest, the feature map and graph, its gaps sort last in the Gaps view and in the MCP tools, and the Gaps view and <strong>Settings → About</strong> say so.</p><h3 id="close-reasons-and-acted-on" tabindex="-1">Close reasons and acted on <a class="header-anchor" href="#close-reasons-and-acted-on" aria-label="Permalink to &quot;Close reasons and acted on&quot;">​</a></h3><p>A closed gap keeps why it closed, shown after its status in the Gaps view:</p><table tabindex="0"><thead><tr><th>Reason</th><th>Closed when</th></tr></thead><tbody><tr><td>Acted on in its pull request</td><td>A run of the pull request that raised it answered it: reached its changed file, answered with its new status, or a test names its intent</td></tr><tr><td>A test reached it</td><td>A test reached its changed file, outside the pull request that raised it</td></tr><tr><td>No longer detected</td><td>Its detector no longer raises it</td></tr><tr><td>Covered by a test</td><td>Someone closed it with <strong>Covered by</strong></td></tr><tr><td>Merged into another gap</td><td>Its subject merged into another one&#39;s</td></tr><tr><td>Detector retired</td><td>Its detector no longer runs</td></tr><tr><td>Out of the coverage scope, file deleted, not observable</td><td>The <a href="/features/uncovered-changes.html">change coverage</a> read of its file</td></tr></tbody></table><p>Beside each detector&#39;s precision, Settings › About counts the gaps it raised on a pull request and how many that pull request acted on. No one triages that number: it says how often a gap led to a test before the change merged.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>A feature groups the routes, pages and controls the tests tagged with it reach. Each recompute also gives it what no feature reaches, with a confidence below one: the controls on its pages (0.8), the pages they link to under the same first path segment (0.6) and those pages&#39; controls (0.5), and the declared routes under the same resource path as a route it reaches, <code>/api/v1/orders</code> for <code>GET /api/v1/orders/:id</code> (0.6). A gap sits under one feature: the one whose tests reach its node, else the most confident inference. A gap on a test sits under the test&#39;s feature, and one on a catalog method under the feature owning most of the pages its URL pattern matches. So the map shows what a feature misses, not only what its tests touch. Dependencies, links, and pages or declared routes under other paths stay ungrouped.</p><p>With three features or more, a node more than half the tests reach, or that more than half the features and three at least group, is a <strong>hub</strong>, such as the session route nearly every test calls. The feature graph still draws it, but it adds no member, test, gap or link to a feature; its gaps sit under <em>Shared by most features</em>. The groups are rebuilt on every recompute, so a feature that loses its tag leaves the map.</p><h2 id="what-the-graph-includes" tabindex="-1">What the graph includes <a class="header-anchor" href="#what-the-graph-includes" aria-label="Permalink to &quot;What the graph includes&quot;">​</a></h2><p>The graph stays proportional to the application&#39;s surface, not its data volume:</p><ul><li><strong>Your own origin only.</strong> Route nodes come from requests to the Playwright <code>baseURL</code> of the run&#39;s projects (or the project&#39;s configured route origins); analytics beacons and CDN assets never become nodes.</li><li><strong>A page load reaches its route.</strong> A page load (<code>page.goto</code>, a link followed) reaches the route of its URL, so a route a backend serves by navigation is reached. <em>Success only</em> counts only the calls a page makes, a form&#39;s POST included, so a page never reads as a route without its error path.</li><li><strong>Pages are path patterns.</strong> <code>/orders/123</code> and <code>/orders/456</code> are one node, as is the same path from staging and production. Numbers, UUIDs, JWTs, ULIDs and long tokens become placeholders; other ids (a Mongo ObjectId, a cuid, a slug) stay in the key, one node per value. A single-page app routed by the URL hash (<code>/#/settings</code>) is one page, <code>/</code>.</li><li><strong>Routes drop the query.</strong> <code>GET /api/orders?page=2</code> and <code>GET /api/orders?status=open</code> are one node, <code>GET /api/orders</code>.</li><li><strong>Controls and links are templated.</strong> Dates, ids and numbers in an accessible name become placeholders, and each page keeps at most 200 controls and 200 links.</li><li><strong>Branches stay separate.</strong> A default-branch run writes the canonical graph; any other branch writes rows tagged with it, so a route added on a pull request never shows as drift on the default branch. Those rows drop when the pull request closes, or after 30 days unseen. Detectors read the canonical graph and the default branch&#39;s runs; change coverage reads every branch.</li><li><strong>Old nodes retire.</strong> A node unseen for 30 complete default-branch runs leaves the graph, unless an open, snoozed or accepted gap other than <em>Surface drift</em> is about it: that node stays until the gap is closed or dismissed, and a <em>Surface drift</em> gap closes with its node. With a <a href="/operate/storage.html#data-retention">retention period</a>, a node goes with the runs that saw it, whatever gap is about it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/scenario-gaps.html">Scenario gaps &amp; the Test Map</a>: the Coverage tab and triage</li><li><a href="/features/probes.html">Probes</a>: the source of the false-comfort and resilience classes</li><li><a href="/guide/concepts.html#test-map">Core concepts</a>: the Test Map vocabulary</li></ul>',29)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
